import React, { useState, useMemo } from 'react';
import { Search, CheckCheck, Clock, User } from 'lucide-react';

const MessagesList = ({ conversations = [], currentConversation, loading, onSelectConversation }) => {
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all');

  // Récupérer userData de manière sécurisée
  const userData = useMemo(() => {
    try {
      const storedData = localStorage.getItem('userData');
      return storedData ? JSON.parse(storedData) : {};
    } catch (error) {
      console.error('Erreur lors du parsing de userData:', error);
      return {};
    }
  }, []);

  const filteredMessages = useMemo(() => {
    let filtered = conversations || [];

    if (search.trim()) {
      filtered = filtered.filter(conv => {
        if (!conv) return false;

        const isUser = userData.id === conv.user_id;

        const otherUserName = isUser
          ? `${conv.admin_first_name || ''} ${conv.admin_last_name || ''}`.toLowerCase()
          : `${conv.first_name || ''} ${conv.last_name || ''}`.toLowerCase();

        const searchLower = search.toLowerCase();
        return otherUserName.includes(searchLower) ||
               (conv.last_message && conv.last_message.toLowerCase().includes(searchLower));
      });
    }

    if (filter === 'unread') {
      filtered = filtered.filter(conv => conv.unread_count > 0);
    }

    return filtered;
  }, [conversations, search, filter, userData.id]);

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
  };

  return (
    <div className="relative h-full flex flex-col bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 overflow-hidden">
      <div className="flex-shrink-0 p-4 sm:p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
        <h2 className="text-lg sm:text-xl font-bold text-neutral-900 dark:text-white mb-4">
          Conversations
        </h2>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-neutral-400" size={18} />
          <input
            type="text"
            placeholder="Rechercher une conversation..."
            value={search}
            onChange={handleSearchChange}
            className="w-full pl-10 pr-4 py-2 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500"
          />
        </div>

        <div className="flex gap-2 mt-4">
          <button
            onClick={() => setFilter('all')}
            className={`px-3 py-1 text-xs font-medium rounded-full transition-all ${
              filter === 'all'
                ? 'bg-primary-500 text-white'
                : 'bg-neutral-200 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-300 dark:hover:bg-neutral-700'
            }`}
          >
            Tous ({conversations.length})
          </button>
          <button
            onClick={() => setFilter('unread')}
            className={`px-3 py-1 text-xs font-medium rounded-full transition-all ${
              filter === 'unread'
                ? 'bg-primary-500 text-white'
                : 'bg-neutral-200 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-300 dark:hover:bg-neutral-700'
            }`}
          >
            Non lus ({conversations.filter(c => c.unread_count > 0).length})
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto">
        {loading ? (
          <div className="p-8 text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500 mx-auto mb-3"></div>
            <p className="text-neutral-500">Chargement des conversations...</p>
          </div>
        ) : filteredMessages.length === 0 ? (
          <div className="p-8 text-center">
            <User className="h-12 w-12 text-neutral-400 mx-auto mb-3" />
            <p className="text-neutral-500">
              {search ? 'Aucune conversation trouvée' : 'Aucune conversation disponible'}
            </p>
            {!search && (
              <p className="text-sm text-neutral-400 mt-2">
                Commencez une nouvelle conversation pour discuter
              </p>
            )}
          </div>
        ) : (
          <div className="divide-y divide-neutral-200/50 dark:divide-neutral-800/50">
            {filteredMessages.map(conversation => {
              const isSelected = currentConversation?.id === conversation.id;
              const isUser = userData.id === conversation.user_id;

              const otherUserName = isUser
                ? `${conversation.admin_first_name || ''} ${conversation.admin_last_name || ''}`.trim()
                : `${conversation.first_name || ''} ${conversation.last_name || ''}`.trim();

              const lastMessageTime = conversation.last_message_time || conversation.created_at;

              return (
                <div
                  key={conversation.id}
                  onClick={() => onSelectConversation(conversation)}
                  className={`p-3 sm:p-4 cursor-pointer transition-all duration-200 hover:bg-primary-50 dark:hover:bg-primary-900/20 ${
                    isSelected
                      ? 'bg-primary-100 dark:bg-primary-900/30 border-l-4 border-primary-500'
                      : ''
                  }`}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="h-8 w-8 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white text-xs font-bold">
                          {otherUserName?.charAt(0).toUpperCase() || '?'}
                        </div>
                        <h3 className="text-sm sm:text-base font-semibold text-neutral-900 dark:text-white truncate">
                          {otherUserName || 'Utilisateur'}
                        </h3>
                        {conversation.unread_count > 0 && (
                          <span className="flex-shrink-0 px-2 py-0.5 text-xs font-bold bg-primary-500 text-white rounded-full">
                            {conversation.unread_count}
                          </span>
                        )}
                      </div>
                      <p className="text-xs sm:text-sm text-neutral-600 dark:text-neutral-400 truncate mt-1">
                        {conversation.last_message || 'Commencez la conversation...'}
                      </p>
                      <div className="flex items-center gap-1 mt-2">
                        <Clock className="w-3 h-3 text-neutral-500" />
                        <span className="text-xs text-neutral-500">
                          {lastMessageTime 
                            ? new Date(lastMessageTime).toLocaleTimeString('fr-FR', {
                                hour: '2-digit',
                                minute: '2-digit'
                              })
                            : 'Nouveau'}
                        </span>
                      </div>
                    </div>
                    <div className="flex-shrink-0">
                      {conversation.unread_count > 0 ? (
                        <CheckCheck className="w-4 h-4 text-primary-500" />
                      ) : (
                        <div className="w-4 h-4 rounded-full bg-green-500"></div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default MessagesList;
